static double get_angle(double const metric[3][3], int const i, int const j) {
    double length_i, length_j;

    length_i = sqrt(metric[i][i]);
    length_j = sqrt(metric[j][j]);

    return acos(metric[i][j] / length_i / length_j) / PI * 180;
}

